mod common;

use common::Harness;
use serde_json::json;

fn create_with(h: &mut Harness, max: u64) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": max}}));
}

fn send(h: &mut Harness, body: &str) -> serde_json::Value {
    h.run(json!({"Command": "SendMessage", "QueueName": "q", "Body": body}))
}

#[test]
fn body_longer_than_limit_is_rejected_in_bytes() {
    let mut h = Harness::new();
    create_with(&mut h, 4);
    assert_eq!(send(&mut h, "abcd")["ok"], true);
    assert_eq!(send(&mut h, "abcde")["error"]["code"], "InvalidParameterValue");
    // Two characters, four bytes in UTF-8: fits. Three characters, six bytes: does not.
    assert_eq!(send(&mut h, "éé")["ok"], true);
    assert_eq!(send(&mut h, "ééé")["error"]["code"], "InvalidParameterValue");
}

#[test]
fn limit_rule_comes_before_fifo_rules() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "f.fifo",
        "Attributes": {"Fifo": true, "MaxMessageBytes": 1}}));
    // No GroupId would be MissingParameter, but the size rule is first.
    let code = h.err(json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "ab"}));
    assert_eq!(code, "InvalidParameterValue");
}

#[test]
fn attribute_range_and_default() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5")] {
        let code = h.err(json!({"Command": "CreateQueue", "QueueName": "q",
            "Attributes": {"MaxMessageBytes": bad}}));
        assert_eq!(code, "InvalidParameterValue");
    }
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1024);
}

#[test]
fn create_again_compares_the_attribute() {
    let mut h = Harness::new();
    create_with(&mut h, 10);
    create_with(&mut h, 10);
    let code = h.err(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(code, "QueueAlreadyExists");
}

#[test]
fn lowering_the_limit_keeps_existing_messages() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(send(&mut h, "long body")["ok"], true);
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 2}}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 2);
    assert_eq!(r["Counts"]["Visible"], 1);
    assert_eq!(send(&mut h, "long body")["error"]["code"], "InvalidParameterValue");
}

#[test]
fn dead_letter_moves_ignore_the_limit() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "dlq",
        "Attributes": {"MaxMessageBytes": 1}}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
        "Attributes": {"DeadLetterQueue": "dlq", "MaxReceiveCount": 1, "VisibilityTimeout": 0}}));
    assert_eq!(send(&mut h, "long body")["ok"], true);
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dlq"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
}
