//! Batch commands (SPEC-feature section 2).

use serde_json::{Value, json};

use super::{Broker, Members, members};
use crate::error::{Error, ErrorCode, Result};
use crate::naming;
use crate::request::Params;

const MAX_ENTRIES: usize = 10;
const MAX_ENTRY_ID_CHARS: usize = 80;

/// A batch entry whose `Id` has been validated.
struct Entry<'a> {
    id: &'a str,
    params: Params<'a>,
}

fn invalid_entry_id() -> Error {
    Error::new(
        ErrorCode::InvalidBatchEntryId,
        "every entry must be an object with an `Id` of 1 to 80 characters from A-Z a-z 0-9 _ -",
    )
}

/// Applies the numbered rules 1 to 4 of a batch command.
fn parse_entries(raw: &[Value]) -> Result<Vec<Entry<'_>>> {
    if raw.is_empty() {
        return Err(Error::new(
            ErrorCode::EmptyBatchRequest,
            "`Entries` has no entry",
        ));
    }
    if raw.len() > MAX_ENTRIES {
        return Err(Error::new(
            ErrorCode::TooManyEntriesInBatchRequest,
            format!("`Entries` has more than {MAX_ENTRIES} entries"),
        ));
    }
    let entries = raw
        .iter()
        .map(|value| {
            let object = value.as_object().ok_or_else(invalid_entry_id)?;
            let params = Params::new(object);
            let id = params
                .string("Id")
                .ok()
                .flatten()
                .filter(|id| naming::is_identifier(id, MAX_ENTRY_ID_CHARS))
                .ok_or_else(invalid_entry_id)?;
            Ok(Entry { id, params })
        })
        .collect::<Result<Vec<_>>>()?;
    for (i, entry) in entries.iter().enumerate() {
        if entries[..i].iter().any(|earlier| earlier.id == entry.id) {
            return Err(Error::new(
                ErrorCode::BatchEntryIdsNotDistinct,
                format!("`Id` `{}` is used twice", entry.id),
            ));
        }
    }
    Ok(entries)
}

impl Broker {
    pub(super) fn send_message_batch(&mut self, params: Params<'_>) -> Result<Members> {
        self.run_batch(params, |broker, name, entry| {
            entry.params.require(&["Body"])?;
            broker.send_to(name, entry.params)
        })
    }

    pub(super) fn delete_message_batch(&mut self, params: Params<'_>) -> Result<Members> {
        self.run_batch(params, |broker, name, entry| {
            entry.params.require(&["ReceiptHandle"])?;
            broker.delete_from(name, entry.params)
        })
    }

    /// Checks the batch-level parameters and rules, then runs `handle` for
    /// each entry in order and sorts the outcomes into `Successful` and
    /// `Failed`.
    fn run_batch(
        &mut self,
        params: Params<'_>,
        mut handle: impl FnMut(&mut Self, &str, &Entry<'_>) -> Result<Members>,
    ) -> Result<Members> {
        params.require(&["QueueName", "Entries"])?;
        let name = params.string("QueueName")?.expect("required");
        let raw = params.array("Entries")?.expect("required");
        self.queue_mut(name)?;
        let entries = parse_entries(raw)?;

        let mut successful = Vec::new();
        let mut failed = Vec::new();
        for entry in &entries {
            match handle(self, name, entry) {
                Ok(mut result) => {
                    result.insert("Id".into(), json!(entry.id));
                    successful.push(Value::Object(result));
                }
                Err(Error { code, message }) => failed.push(json!({
                    "Id": entry.id,
                    "error": { "code": code.as_str(), "message": message },
                })),
            }
        }
        Ok(members([
            ("Successful", Value::Array(successful)),
            ("Failed", Value::Array(failed)),
        ]))
    }
}
