mod common;

use common::Harness;
use serde_json::{Value, json};

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn list(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn tags_start_empty_and_are_set_and_replaced() {
    let mut h = setup();
    assert_eq!(list(&mut h), json!({}));
    assert_eq!(tag(&mut h, json!({"a": "1", "b": ""}))["ok"], true);
    assert_eq!(tag(&mut h, json!({"a": "2"}))["ok"], true);
    assert_eq!(list(&mut h), json!({"a": "2", "b": ""}));
    assert_eq!(tag(&mut h, json!({}))["ok"], true);
    assert_eq!(list(&mut h), json!({"a": "2", "b": ""}));
}

#[test]
fn keys_are_case_sensitive() {
    let mut h = setup();
    tag(&mut h, json!({"k": "1", "K": "2"}));
    assert_eq!(list(&mut h), json!({"K": "2", "k": "1"}));
}

#[test]
fn invalid_keys_and_values() {
    let mut h = setup();
    let cases = [
        json!({"": "v"}),
        json!({"a b": "v"}),
        json!({"k".repeat(129): "v"}),
        json!({"k": 1}),
        json!({"k": null}),
        json!({"k": "v".repeat(257)}),
        json!({"k": "é".repeat(129)}),
    ];
    for tags in cases {
        assert_eq!(tag(&mut h, tags.clone())["error"]["code"], "InvalidParameterValue", "{tags}");
    }
    assert_eq!(tag(&mut h, json!({"k".repeat(128): "v".repeat(256)}))["ok"], true);
    assert_eq!(tag(&mut h, json!({"u": "é".repeat(128)}))["ok"], true);
    assert_eq!(list(&mut h).as_object().unwrap().len(), 2);
}

#[test]
fn invalid_value_wins_over_missing_queue_and_limit() {
    let mut h = Harness::new();
    let code = h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"k": 1}}));
    assert_eq!(code, "InvalidParameterValue");
    let code = h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}}));
    assert_eq!(code, "QueueDoesNotExist");
    let code = h.err(json!({"Command": "TagQueue", "QueueName": "nope"}));
    assert_eq!(code, "MissingParameter");
    let code = h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": []}));
    assert_eq!(code, "InvalidParameterValue");
}

#[test]
fn fifty_tags_fit_and_fifty_one_do_not() {
    let mut h = setup();
    let many = |range: std::ops::Range<u32>| -> Value {
        range.map(|i| (format!("k{i}"), json!("v"))).collect::<serde_json::Map<_, _>>().into()
    };
    assert_eq!(tag(&mut h, many(0..50))["ok"], true);
    // Replacing existing keys adds nothing.
    assert_eq!(tag(&mut h, json!({"k0": "new"}))["ok"], true);
    let r = tag(&mut h, json!({"extra": "v"}));
    assert_eq!(r["error"]["code"], "LimitExceeded");
    assert_eq!(list(&mut h).as_object().unwrap().len(), 50);
    // A failed command changes nothing, even for the keys that would fit.
    let r = tag(&mut h, json!({"k0": "again", "extra": "v"}));
    assert_eq!(r["error"]["code"], "LimitExceeded");
    assert_eq!(list(&mut h)["k0"], "new");
}

#[test]
fn untag_removes_and_ignores_unknown_keys() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1", "b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]}));
    assert_eq!(list(&mut h), json!({"b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(list(&mut h), json!({"b": "2"}));
}

#[test]
fn untag_validates_keys_before_removing_any() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    for keys in [json!(["a", 1]), json!(["a", "b c"]), json!(["a", ""])] {
        let code = h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": keys}));
        assert_eq!(code, "InvalidParameterValue");
    }
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": "a"})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(list(&mut h), json!({"a": "1"}));
}

#[test]
fn missing_queue_is_reported() {
    let mut h = Harness::new();
    for command in ["ListQueueTags", "UntagQueue", "TagQueue"] {
        let code = h.err(json!({"Command": command, "QueueName": "nope", "Tags": {}, "TagKeys": []}));
        assert_eq!(code, "QueueDoesNotExist", "{command}");
    }
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Attributes"].clone();
    assert!(attrs.get("Tags").is_none());
    // CreateQueue rule 4 ignores tags.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(list(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(list(&mut h), json!({}));
}
