fn untag_validates_keys_before_removing_any() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    for keys in [json!(["a", 1]), json!(["a", "b c"]), json!(["a", ""])] {
        let code = h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": keys}));
        assert_eq!(code, "InvalidParameterValue");
    }
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": "a"})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(list(&mut h), json!({"a": "1"}));
}

#[test]
fn missing_queue_is_reported() {
    let mut h = Harness::new();
    for command in ["ListQueueTags", "UntagQueue", "TagQueue"] {
        let code = h.err(json!({"Command": command, "QueueName": "nope", "Tags": {}, "TagKeys": []}));
        assert_eq!(code, "QueueDoesNotExist", "{command}");
    }
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Attributes"].clone();
    assert!(attrs.get("Tags").is_none());
    // CreateQueue rule 4 ignores tags.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(list(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(list(&mut h), json!({}));
}
